const body = $input.first().json.body || $input.first().json;

const message = body.message || body.text || body.patient_message || "";
let eegCsv = body.eeg_csv || body.csv || body.eeg || "";
let preference = (body.preference || body.mode || "research-grade").toLowerCase().trim();

const validPrefs = ["fast", "detailed", "research-grade", "explainable"];
if (!validPrefs.includes(preference)) preference = "research-grade";

if (eegCsv && eegCsv.startsWith("data:")) {
  eegCsv = eegCsv.split(",")[1] || eegCsv;
}
if (eegCsv && /^[A-Za-z0-9+/=]+$/.test(eegCsv.substring(0, 80))) {
  try { eegCsv = Buffer.from(eegCsv, "base64").toString("utf8"); } catch(e) {}
}

return [{
  json: {
    patient_message: message,
    eeg_csv: eegCsv,
    has_eeg: !!(eegCsv && eegCsv.length > 40),
    preference: preference,
    session_id: body.session_id || body.patient_id || `sess_${Date.now()}`,
    timestamp: new Date().toISOString()
  }
}];

